INSERT INTO `carpet_repairs` (`id`, `description`, `kachaee_number`, `price`, `total_price`, `af_total_price`, `currency_code`, `exchange_rate`, `base_currency_amount`, `override_debit_account_id`, `override_credit_account_id`, `inventory_transaction_id`, `date`, `carpetId`, `team_id`, `created_at`, `updated_at`) VALUES
(1, 'از حق مراد قالین مراکن ZN گیلم آنرا یک طرف جور کرده', 'Kachayee-2026-0001', '2.00', '8.66', '8.66', 'USD', 1.000000, 8.66, NULL, NULL, NULL, '2026-08-18', 193, 1, '2026-08-18 11:43:00', '2026-08-18 11:43:00'),
(2, 'قاری حق مراد - از درک ترمیم گلیمه یکطرفه یک تخته قالین ماراکن ZN  به مبلغ 11.92 دالر به حساب نورالدین کچایگر جمع گردید', 'Kachayee-2026-0001', '2.00', '11.92', '11.92', 'USD', 1.000000, 11.92, NULL, NULL, NULL, '2026-08-18', 194, 1, '2026-08-18 12:01:47', '2026-08-21 19:25:30'),
(3, 'استاد منان شمالی،  از درک ترمیم یک تخته قالین درختک سبز فی متر 300 افغانی کچایی حاشیه برابر شده است(   جمله پول 2232 افغانی به حساب نورالدین جمع گردید', 'Kachayee-2026-0001', '300.00', '34.34', '2232.00', 'AFN', 65.000023, 34.34, NULL, NULL, NULL, '2026-08-19', 166, 1, '2026-08-19 14:44:04', '2026-08-19 14:44:04'),
(4, 'کچای بدوش شرکت ( از درک ترمیم یک تخته قالین 25x25 جهت سیده کاری و چوقک به مبلغ 1077 افغانی به حساب نورالدین جمع گردید)', 'Kachayee-2026-0001', '150.00', '16.57', '1077.00', 'AFN', 65.000023, 16.57, NULL, NULL, NULL, '2026-08-19', 951, 1, '2026-08-19 15:04:51', '2026-08-21 19:24:49'),
(5, 'شریف شمالی  از درک ترمیم سیده کاری دو طرفه یک تخته آردر 45x45  ZN به مبلغ 420 افغانی به حساب نورالدین جمع گردید', 'Kachayee-2026-0001', '200.00', '6.49', '420.00', 'AFN', 64.700002, 6.49, NULL, NULL, NULL, '2026-08-19', 1548, 1, '2026-08-19 15:09:48', '2026-08-21 19:26:29'),
(6, 'این قالین قبلا کچایی شده توسط نورالدین', 'Kachayee-2026-0001', '150.00', '9.40', '607.50', 'AFN', 64.600026, 9.40, 1, 4, NULL, '2026-08-24', 1087, 1, '2026-08-24 15:14:18', '2026-08-24 15:14:18');
